169:      syncState?.includesBaseElement,
170:      activeId === null,
171:    ),
172:    moves: defaultValue(syncState?.moves, 0),
173:    orientation: defaultValue(
174:      props.orientation,
175:      syncState?.orientation,
176:      "both" as const,
177:    ),
178:    rtl: defaultValue(props.rtl, syncState?.rtl, false),
179:    virtualFocus: defaultValue(
180:      props.virtualFocus,
181:      syncState?.virtualFocus,
182:      false,
183:    ),
184:    focusLoop: defaultValue(props.focusLoop, syncState?.focusLoop, false),
185:    focusWrap: defaultValue(props.focusWrap, syncState?.focusWrap, false),
186:    focusShift: defaultValue(props.focusShift, syncState?.focusShift, false),
187:  };
