194:    sync(composite, ["renderedItems", "activeId"], (state) => {
195:      composite.setState("activeId", (activeId) => {
196:        if (activeId !== undefined) return activeId;
197:        return findFirstEnabledItem(state.renderedItems)?.id;
198:      });
199:    }),
200:  );
