202:  const getNextId = (
203:    direction: "next" | "previous" | "up" | "down" = "next",
204:    options: NextOptions = {},
205:  ): string | null | undefined => {
206:    const defaultState = composite.getState();
207:    const {
208:      skip = 0,
209:      activeId = defaultState.activeId,
210:      focusShift = defaultState.focusShift,
211:      focusLoop = defaultState.focusLoop,
212:      focusWrap = defaultState.focusWrap,
213:      includesBaseElement = defaultState.includesBaseElement,
214:      renderedItems = defaultState.renderedItems,
215:      rtl = defaultState.rtl,
216:    } = options;
217:
218:    const isVerticalDirection = direction === "up" || direction === "down";
219:    const isNextDirection = direction === "next" || direction === "down";
220:
221:    const canReverse = isNextDirection
