238:      return findFirstEnabledItem(items)?.id;
239:    }
240:
241:    const activeItem = items.find((item) => item.id === activeId);
242:    if (!activeItem) {
243:      // If there's no item focused, we just move to the first one.
244:      return findFirstEnabledItem(items)?.id;
245:    }
