293:      return nextItem?.id;
294:    }
295:
296:    if (canWrap) {
297:      const nextItem = findFirstEnabledItem(
298:        // We can use nextItems, which contains all the next items, including
299:        // items from other rows, to wrap between rows. However, if there is a
300:        // null item (the composite container), we'll only use the next items in
301:        // the row. So moving next from the last item will focus on the
302:        // composite container. On grid composites, horizontal navigation never
303:        // focuses on the composite container, only vertical.
304:        hasNullItem ? nextItemsInRow : nextItems,
305:        activeId,
306:      );
307:      const nextId = hasNullItem ? nextItem?.id || null : nextItem?.id;
308:      return nextId;
309:    }
310:
311:    const nextItem = findFirstEnabledItem(nextItemsInRow, activeId);
312:    if (!nextItem && hasNullItem) {
313:      return null;
314:    }
315:    return nextItem?.id;
316:  };
