332:    first: () => findFirstEnabledItem(composite.getState().renderedItems)?.id,
333:    last: () =>
334:      findFirstEnabledItem(reverseArray(composite.getState().renderedItems))
335:        ?.id,
336:
337:    next: (options) => {
338:      if (options !== undefined && typeof options === "number") {
339:        options = { skip: options };
340:      }
341:      return getNextId("next", options);
342:    },
343:
344:    previous: (options) => {
