346:        options = { skip: options };
347:      }
348:      return getNextId("previous", options);
349:    },
350:
351:    down: (options) => {
352:      if (options !== undefined && typeof options === "number") {
353:        options = { skip: options };
354:      }
355:      return getNextId("down", options);
356:    },
357:
358:    up: (options) => {
359:      if (options !== undefined && typeof options === "number") {
360:        options = { skip: options };
361:      }
362:      return getNextId("up", options);
363:    },
364:  };
