import * as Ariakit from "@ariakit/react";
import "./style.css";

export default function Example() {
  const checkbox = Ariakit.useCheckboxStore({ defaultValue: false });
  const focusTrapped = Ariakit.useStoreState(checkbox, "value");
  return (
    <Ariakit.FocusTrapRegion className="wrapper" enabled={focusTrapped}>
      <label className="label">
        <Ariakit.Checkbox store={checkbox} className="checkbox" />
        Trap focus
      </label>
      <Ariakit.Button className="button">Button 1</Ariakit.Button>
      <Ariakit.Button className="button">Button 2</Ariakit.Button>
      <Ariakit.Button className="button" disabled>
        Button 3
      </Ariakit.Button>
      <input className="input" title="one" placeholder="Input" />
      <input
        className="input"
        title="two"
        disabled
        placeholder="Disabled input"
      />
    </Ariakit.FocusTrapRegion>
  );
}
import { press, q } from "@ariakit/test";

function setup() {
  const before = document.createElement("div");
  before.tabIndex = 0;
  before.textContent = "Before";
  const after = before.cloneNode() as HTMLDivElement;
  after.textContent = "After";
  document.body.prepend(before);
  document.body.append(after);
  return () => {
    before.remove();
    after.remove();
  };
}

test("correctly traps focus in region", async () => {
  const cleanup = setup();
  await press.Tab();
  expect(q.text("Before")).toHaveFocus();
  await press.Tab();
  expect(q.checkbox()).toHaveFocus();
  await press.Space(q.checkbox());
  await press.Tab();
  expect(q.button("Button 1")).toHaveFocus();
  await press.Tab();
  expect(q.button("Button 2")).toHaveFocus();
  await press.Tab();
  expect(q.textbox("one")).toHaveFocus();
  await press.Tab();
  // looped
  expect(q.checkbox()).toHaveFocus();
  cleanup();
});

test("correctly releases focus from region", async () => {
  const cleanup = setup();
  await press.Tab();
  expect(q.text("Before")).toHaveFocus();
  await press.Tab();
  expect(q.checkbox()).toHaveFocus();
  await press.Space(q.checkbox());
  await press.Tab();
  expect(q.button("Button 1")).toHaveFocus();
  await press.Tab();
  expect(q.button("Button 2")).toHaveFocus();
  await press.Tab();
  expect(q.textbox("one")).toHaveFocus();
  await press.Tab();
  await press.Space(q.checkbox());
  await press.Tab();
  await press.Tab();
  await press.Tab();
  await press.Tab();
  expect(q.text("After")).toHaveFocus();
  cleanup();
});
import { getAllTabbableIn } from "@ariakit/core/utils/focus";
import { removeUndefinedValues } from "@ariakit/core/utils/misc";
import { useRef } from "react";
import type { ElementType } from "react";
import { useMergeRefs, useWrapElement } from "../utils/hooks.ts";
import { createElement, createHook, forwardRef } from "../utils/system.tsx";
import type { Options, Props } from "../utils/types.ts";
import { FocusTrap } from "./focus-trap.tsx";

const TagName = "div" satisfies ElementType;
type TagName = typeof TagName;
type HTMLType = HTMLElementTagNameMap[TagName];

/**
 * Returns props to create a `FocusTrapRegion` component.
 * @see https://ariakit.org/components/focus-trap-region
 * @example
 * ```jsx
 * const props = useFocusTrapRegion();
 * <Role {...props} />
 * ```
 */
export const useFocusTrapRegion = createHook<TagName, FocusTrapRegionOptions>(
  function useFocusTrapRegion({ enabled = false, ...props }) {
    const ref = useRef<HTMLType>(null);

    props = useWrapElement(
      props,
      (element) => {
        const renderFocusTrap = () => {
          if (!enabled) return null;
          return (
            <FocusTrap
              onFocus={(event) => {
                const container = ref.current;
                if (!container) return;
                const tabbables = getAllTabbableIn(container, true);
                const first = tabbables[0];
                const last = tabbables[tabbables.length - 1];
                // Fallbacks to the container element
                if (!tabbables.length) {
                  container.focus();
                  return;
                }
                if (event.relatedTarget === first) {
                  last?.focus();
                } else {
                  first?.focus();
                }
              }}
            />
          );
        };
        return (
          <>
            {renderFocusTrap()}
            {element}
            {renderFocusTrap()}
          </>
        );
